+    private List<String> readLines(String fileName) {
+        Path file = pathForNameOrNull(fileName);
+        if (file == null) {
+            throw new StoreReadException(new IOException("Invalid rule violation file name: " + fileName));
+        }
+        try {
+            String text = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
+            List<String> result = new ArrayList<>();
+            StringBuilder line = new StringBuilder();
+            for (int i = 0; i < text.length(); i++) {
+                char character = text.charAt(i);
+                if ((character == '\r' || character == '\n') && !isEscaped(line)) {
+                    if (line.length() > 0) {
+                        result.add(unescape(line.toString()));
+                    }
+                    line.setLength(0);
+                    if (character == '\r' && i + 1 < text.length() && text.charAt(i + 1) == '\n') {
+                        i++;
+                    }
+                } else {
+                    line.append(character);
+                }
+            }
+            if (line.length() > 0) {
+                result.add(unescape(line.toString()));
+            }
+            return result;
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
