/**
 * A text file based implementation of a {@link ViolationStore}.<br>
 * This {@link ViolationStore} stores the violations of every single
 * {@link FreezingArchRule} in a dedicated file and keeps an index named
 * {@code stored.rules} in the same folder.
 *
 * <p>The store can be configured through the following properties:</p>
 * <pre><code>
 * default.path=...               # path of the folder where violation files are stored
 * default.allowStoreCreation=... # whether a new index file may be created
 * default.allowStoreUpdate=...   # whether store files may be changed
 * default.fileNames=random       # random, description, or a strategy class name
 * default.integrity=ignore       # ignore, repair, or fail
 * </code></pre>
 */
@PublicAPI(usage = ACCESS)
public final class TextFileBasedViolationStore implements ViolationStore {
    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);

    private static final Pattern DESCRIPTION_WORD = Pattern.compile("(?<![A-Za-z0-9_])([A-Za-z0-9]{4,120})(?![A-Za-z0-9_])");
    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
    private static final String STORE_PATH_DEFAULT = "archunit_store";
    private static final String STORED_RULES_FILE_NAME = "stored.rules";
    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
    private static final String INTEGRITY_DEFAULT = "ignore";
    private static final String RANDOM_FILE_NAMES = "random";
    private static final String DESCRIPTION_FILE_NAMES = "description";

    /* A JVM-local lock is sufficient for the concurrency guarantee of this store. */
    private static final ConcurrentHashMap<String, Object> STORE_LOCKS = new ConcurrentHashMap<>();

    private final RuleViolationFileNameStrategy constructorStrategy;
    private final boolean strategyWasPassedToConstructor;

    private RuleViolationFileNameStrategy activeStrategy;
    private boolean randomFileNames;
    private boolean storeCreationAllowed;
    private boolean storeUpdateAllowed;
    private String integrityMode;
    private File storeFolder;
    private Path storedRulesFile;
    private Object storeLock;
    private FileSyncedProperties storedRules;

    /**
     * Creates a standard store that names new violation files with random UUIDs.
     *
     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
     */
    public TextFileBasedViolationStore() {
        constructorStrategy = null;
        strategyWasPassedToConstructor = false;
    }

    /**
     * Creates a store with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        constructorStrategy = ruleViolationFileNameStrategy;
        strategyWasPassedToConstructor = true;
    }

    @Override
    public void initialize(Properties properties) {
        Properties configuration = properties == null ? new Properties() : properties;
        configure(configuration);

        storeFolder = new File(configuration.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
        storedRulesFile = storeFolder.toPath().resolve(STORED_RULES_FILE_NAME);
        try {
            storeLock = STORE_LOCKS.computeIfAbsent(storedRulesFile.toFile().getCanonicalPath(), ignored -> new Object());
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }

        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile.toAbsolutePath());
        synchronized (storeLock) {
            initializeWhileLocked();
        }
    }

    private void configure(Properties properties) {
        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));

        integrityMode = properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT);
        if (!"repair".equals(integrityMode) && !"fail".equals(integrityMode) && !"ignore".equals(integrityMode)) {
            throw new StoreInitializationFailedException(String.format(
                    "Invalid %s value '%s'; accepted values are repair, fail and ignore",
                    INTEGRITY_PROPERTY_NAME, integrityMode));
        }
        if ("repair".equals(integrityMode) && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "%s=repair requires %s=true", INTEGRITY_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        String fileNames = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
        if (strategyWasPassedToConstructor) {
            if (fileNames != null) {
                throw new StoreInitializationFailedException(String.format(
                        "%s cannot be configured for a store constructed with a naming strategy", FILE_NAMES_PROPERTY_NAME));
            }
            activeStrategy = constructorStrategy;
            randomFileNames = false;
        } else if (fileNames == null || RANDOM_FILE_NAMES.equals(fileNames)) {
            activeStrategy = ignored -> UUID.randomUUID().toString();
            randomFileNames = true;
        } else if (DESCRIPTION_FILE_NAMES.equals(fileNames)) {
            activeStrategy = new DescriptionRuleViolationFileNameStrategy();
            randomFileNames = false;
        } else {
            activeStrategy = instantiateStrategy(fileNames);
            randomFileNames = false;
        }
    }

    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
        try {
            Class<?> strategyType = Class.forName(className);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)) {
                throw new IllegalArgumentException("does not implement " + RuleViolationFileNameStrategy.class.getName());
            }
            if (!Modifier.isPublic(strategyType.getModifiers())) {
                throw new IllegalArgumentException("is not public");
            }
            Constructor<?> constructor = strategyType.getConstructor();
            if (!Modifier.isPublic(constructor.getModifiers())) {
                throw new IllegalArgumentException("has no public no-argument constructor");
            }
            return (RuleViolationFileNameStrategy) constructor.newInstance();
        } catch (Exception e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not instantiate %s configured through %s='%s' (the value must be 'random', 'description', or a strategy with a public no-argument constructor)",
                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, className), e);
        }
    }

    private void initializeWhileLocked() {
        Path folderPath = storeFolder.toPath();
        boolean folderExists = Files.exists(folderPath, LinkOption.NOFOLLOW_LINKS);
        if (!folderExists) {
            if (!storeCreationAllowed) {
                throw new StoreInitializationFailedException(String.format(
                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
            }
            try {
                Files.createDirectories(folderPath);
            } catch (IOException e) {
                throw new StoreInitializationFailedException(e);
            }
        }
        if (!Files.isDirectory(folderPath)) {
            throw new StoreInitializationFailedException(String.format("Violation store folder is not a directory: %s", storeFolder.getAbsolutePath()));
        }


        boolean indexExists = Files.exists(storedRulesFile, LinkOption.NOFOLLOW_LINKS);
        if (indexExists && !Files.isRegularFile(storedRulesFile, LinkOption.NOFOLLOW_LINKS)) {
            throw new StoreInitializationFailedException(String.format(
                    "Violation store index is not a regular file directly in the store folder: %s", storedRulesFile));
        }
        if (!indexExists && !storeCreationAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
        }

        Properties properties = indexExists ? loadProperties(storedRulesFile) : new Properties();
        IntegrityReport report = "ignore".equals(integrityMode)
                ? new IntegrityReport(new ArrayList<>(), new ArrayList<>())
                : inspect(properties);

        if ("fail".equals(integrityMode) && report.hasProblems()) {
            throw new StoreInitializationFailedException(report.message(storeUpdateAllowed));
        }

        boolean indexChanged = false;
        if ("repair".equals(integrityMode)) {
            indexChanged = repair(report, properties);
        }
        if (!indexExists || indexChanged) {
            syncProperties(properties);
        }
        storedRules = new FileSyncedProperties(properties);
    }

    private Properties loadProperties(Path file) {
        Properties result = new Properties();
        try (InputStream inputStream = new FileInputStream(file.toFile())) {
            result.load(inputStream);
            return result;
        } catch (IOException | IllegalArgumentException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private void syncProperties(Properties properties) {
        Path temporaryFile = null;
        try {
            temporaryFile = Files.createTempFile(storeFolder.toPath(), ".stored.rules.", ".tmp");
            try (OutputStream outputStream = Files.newOutputStream(temporaryFile, StandardOpenOption.TRUNCATE_EXISTING)) {
                properties.store(outputStream, "");
            }
            moveReplacing(temporaryFile, storedRulesFile);
            temporaryFile = null;
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        } finally {
            deleteQuietly(temporaryFile);
        }
    }

    private void moveReplacing(Path source, Path target) throws IOException {
        try {
            Files.move(source, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        } catch (AtomicMoveNotSupportedException e) {
            Files.move(source, target, StandardCopyOption.REPLACE_EXISTING);
        }
    }

    private void refreshStoredRules() {
        storedRules = new FileSyncedProperties(loadProperties(storedRulesFile));
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (storeLock) {
            refreshStoredRules();
            return findRuleKey(storedRules.properties, rule.getDescription()) != null;
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }
        synchronized (storeLock) {
            refreshStoredRules();
            String ruleKey = findRuleKey(storedRules.properties, rule.getDescription());
            if (violations.isEmpty() && "repair".equals(integrityMode)) {
                forgetRuleWithoutViolations(ruleKey);
                return;
            }
            if (violations.isEmpty() && ruleKey == null) {
                return;
            }

            String fileName = ruleKey == null
                    ? nameForDescription(rule.getDescription())
                    : storedRules.properties.getProperty(ruleKey);
            Path ruleFile = validateSaveName(fileName, ruleKey, storedRules.properties);
            boolean fileExisted = Files.exists(ruleFile, LinkOption.NOFOLLOW_LINKS);
            writeViolations(violations, ruleFile);

            if (ruleKey == null) {
                storedRules.properties.setProperty(rule.getDescription(), fileName);
                try {
                    syncProperties(storedRules.properties);
                } catch (RuntimeException e) {
                    if (!fileExisted) {
                        deleteQuietly(ruleFile);
                    }
                    throw e;
                }
            }
        }
    }

    private void forgetRuleWithoutViolations(String ruleKey) {
        if (ruleKey == null) {
            return;
        }
        String fileName = storedRules.properties.getProperty(ruleKey);
        Path ruleFile = validateSaveName(fileName, ruleKey, storedRules.properties);
        if (!isSharedFile(ruleKey, fileName, storedRules.properties)) {
            deleteRuleFileForUpdate(ruleFile);
        }
        storedRules.properties.remove(ruleKey);
        syncProperties(storedRules.properties);
    }

    private boolean isSharedFile(String ownKey, String ownName, Properties properties) {
        Path ownPath = pathForName(ownName);
        for (String key : properties.stringPropertyNames()) {
            if (key.equals(ownKey)) {
                continue;
            }
            String otherName = properties.getProperty(key);
            if (ownName.equals(otherName)) {
                return true;
            }
            Path otherPath = pathForNameOrNull(otherName);
            if (ownPath != null && otherPath != null && sameFile(ownPath, otherPath)) {
                return true;
            }
        }
        return false;
    }

    private String nameForDescription(String description) {
        if (activeStrategy == null) {
            throw new StoreUpdateFailedException("The rule violation file name strategy returned no name");
        }
        String name;
        try {
            name = activeStrategy.createRuleFileName(description);
        } catch (RuntimeException e) {
            throw new StoreUpdateFailedException(e);
        }
        if (name == null || name.isEmpty()) {
            throw new StoreUpdateFailedException("The rule violation file name strategy returned no name");
        }
        return name;
    }

    private Path validateSaveName(String fileName, String ownKey, Properties properties) {
        if (fileName == null || fileName.isEmpty()) {
            throw new StoreUpdateFailedException("The rule violation file name strategy returned no name");
        }
        Path path;
        try {
            path = pathForName(fileName);
        } catch (RuntimeException e) {
            throw new StoreUpdateFailedException(String.format("Invalid rule violation file name '%s'", fileName));
        }
        if (path == null || !isDirectChild(path)) {
            throw new StoreUpdateFailedException(String.format(
                    "Rule violation file name '%s' does not name a file directly in the store folder", fileName));
        }
        if (isIndex(path)) {
            throw new StoreUpdateFailedException(String.format(
                    "Rule violation file name '%s' names the store index", fileName));
        }

        boolean recordedByOwnEntry = ownKey != null && fileName.equals(properties.getProperty(ownKey));
        if (!recordedByOwnEntry) {
            for (String name : properties.stringPropertyNames()) {
                if (fileName.equals(properties.getProperty(name))) {
                    throw new StoreUpdateFailedException(String.format(
                            "Rule violation file name '%s' is recorded by another entry", fileName));
                }
            }
            if (Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
                throw new StoreUpdateFailedException(String.format(
                        "Rule violation file name '%s' names a file not recorded by its own entry", fileName));
            }
        }

        if (Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
            Path target;
            try {
                target = path.toRealPath();
            } catch (IOException e) {
                throw new StoreUpdateFailedException(String.format(
                        "Rule violation file name '%s' does not lead to a file directly in the store folder", fileName));
            }
            if (!target.getParent().equals(realFolder())) {
                throw new StoreUpdateFailedException(String.format(
                        "Rule violation file name '%s' does not lead directly into the store folder", fileName));
            }
            if (!Files.isRegularFile(target)) {
                throw new StoreUpdateFailedException(String.format(
                        "Rule violation file name '%s' does not lead to a regular file", fileName));
            }
        }
        if (sameFile(path, storedRulesFile)) {
            throw new StoreUpdateFailedException(String.format(
                    "Rule violation file name '%s' names the store index", fileName));
        }
        return path;
    }

    private void writeViolations(List<String> violations, Path ruleFile) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append('\n');
        }
        byte[] content = builder.toString().getBytes(StandardCharsets.UTF_8);
        try {
            if (Files.exists(ruleFile, LinkOption.NOFOLLOW_LINKS)) {
                Files.write(ruleFile.toRealPath(), content, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
            } else {
                Path temporaryFile = Files.createTempFile(storeFolder.toPath(), ".archunit-violation.", ".tmp");
                try {
                    Files.write(temporaryFile, content, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
                    Files.move(temporaryFile, ruleFile, StandardCopyOption.ATOMIC_MOVE);
                    temporaryFile = null;
                } catch (AtomicMoveNotSupportedException e) {
                    Files.move(temporaryFile, ruleFile);
                    temporaryFile = null;
                } finally {
                    deleteQuietly(temporaryFile);
                }
            }
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private String escape(String violation) {
        StringBuilder result = new StringBuilder(violation.length());
        for (int i = 0; i < violation.length(); i++) {
            char character = violation.charAt(i);
            if (character == '\r' || character == '\n') {
                result.append('\\');
            }
            result.append(character);
        }
        return result.toString();
    }

    private String unescape(String violation) {
        return violation.replace("\\\r", "\r").replace("\\\n", "\n");
    }

    @Override
    public List<String> getViolations(ArchRule rule) {
        synchronized (storeLock) {
            refreshStoredRules();
            String key = findRuleKey(storedRules.properties, rule.getDescription());
            checkArgument(key != null, "No rule stored with description '%s'", rule.getDescription());
            List<String> result = readLines(storedRules.properties.getProperty(key));
            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
            return result;
        }
    }

    private List<String> readLines(String fileName) {
        Path file = pathForNameOrNull(fileName);
        if (file == null) {
            throw new StoreReadException(new IOException("Invalid rule violation file name: " + fileName));
        }
        try {
            String text = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
            List<String> result = new ArrayList<>();
            StringBuilder line = new StringBuilder();
            for (int i = 0; i < text.length(); i++) {
                char character = text.charAt(i);
                if ((character == '\r' || character == '\n') && !isEscaped(line)) {
                    if (line.length() > 0) {
                        result.add(unescape(line.toString()));
                    }
                    line.setLength(0);
                    if (character == '\r' && i + 1 < text.length() && text.charAt(i + 1) == '\n') {
                        i++;
                    }
                } else {
                    line.append(character);
                }
            }
            if (line.length() > 0) {
                result.add(unescape(line.toString()));
