Wall time 0.1 seconds
Output:
'}, {'type': 'input_text', 'text': '            return result;
        } catch (IOException e) {
            throw new StoreReadException(e);
        }
    }

    private boolean isEscaped(StringBuilder text) {
        int slashes = 0;
        for (int i = text.length() - 1; i >= 0 && text.charAt(i) == '\\'; i--) {
            slashes++;
        }
        return slashes % 2 == 1;
    }

    private IntegrityReport inspect(Properties properties) {
        List<Entry> entries = new ArrayList<>();
        for (String description : properties.stringPropertyNames()) {
            String fileName = properties.getProperty(description);
            String derived = deriveForEntry(description, fileName);
            Entry entry = new Entry(description, fileName, derived, pathForNameOrNull(fileName));
            entry.direct = entry.path != null && isDirectChild(entry.path);
            entry.regular = entry.direct && Files.isRegularFile(entry.path);
            entry.index = entry.path != null && isIndex(entry.path);
            entry.broken = !entry.regular || entry.index;
            if (!entry.broken) {
                try {
                    entry.target = entry.path.toRealPath();
                    entry.resolved = readLines(fileName).isEmpty();
                } catch (IOException | StoreReadException e) {
                    throw new StoreInitializationFailedException(e);
                }
            }
            entry.misplaced = !fileName.equals(derived);
            entries.add(entry);
        }

        Map<String, List<Entry>> byName = new HashMap<>();
        Map<String, List<Entry>> byDerivedName = new HashMap<>();
        for (Entry entry : entries) {
            addTo(byName, entry.fileName, entry);
            addTo(byDerivedName, entry.derived, entry);
        }
        for (List<Entry> sameName : byName.values()) {
            if (sameName.size() > 1) {
                for (Entry entry : sameName) {
                    entry.shared = true;
                }
            }
        }
        for (int i = 0; i < entries.size(); i++) {
            for (int j = i + 1; j < entries.size(); j++) {
                Entry left = entries.get(i);
                Entry right = entries.get(j);
                if (left.target != null && right.target != null && sameFile(left.target, right.target)) {
                    left.shared = true;
                    right.shared = true;
                }
            }
        }
        for (List<Entry> sameDerivedName : byDerivedName.values()) {
            if (sameDerivedName.size() > 1) {
                for (Entry entry : sameDerivedName) {
                    entry.colliding = true;
                }
            }
        }
        for (Entry entry : entries) {
            entry.occupied = entry.misplaced && isOccupied(entry, entries);
        }

        List<Path> unownedFiles = findUnownedFiles(entries);
        return new IntegrityReport(entries, unownedFiles);
    }

    private String deriveForEntry(String description, String recordedName) {
        if (randomFileNames) {
            return recordedName;
        }
        if (activeStrategy == null) {
            throw new StoreInitializationFailedException("The rule violation file name strategy returned no name");
        }
        String derived;
        try {
            derived = activeStrategy.createRuleFileName(description);
        } catch (RuntimeException e) {
            throw new StoreInitializationFailedException(e);
        }
        if (derived == null || derived.isEmpty()) {
            throw new StoreInitializationFailedException("The rule violation file name strategy returned no name");
        }
        return derived;
    }

    private boolean isOccupied(Entry entry, List<Entry> entries) {
        Path derivedPath = pathForNameOrNull(entry.derived);
        if (derivedPath == null || !isDirectChild(derivedPath) || isIndex(derivedPath)) {
            return true;
        }
        if (Files.exists(derivedPath, LinkOption.NOFOLLOW_LINKS)) {
            return true;
        }
        for (Entry other : entries) {
            if (other != entry && entry.derived.equals(other.fileName)) {
                return true;
            }
        }
        return false;
    }

    private List<Path> findUnownedFiles(List<Entry> entries) {
        List<Path> result = new ArrayList<>();
        try (DirectoryStream<Path> children = Files.newDirectoryStream(storeFolder.toPath())) {
            for (Path child : children) {
                if (!child.toAbsolutePath().normalize().equals(storedRulesFile.toAbsolutePath().normalize())
                        && Files.isRegularFile(child, LinkOption.NOFOLLOW_LINKS)
                        && !isOwnedByEntry(child, entries)) {
                    result.add(child);
                }
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
        result.sort(Comparator.comparing(path -> path.getFileName().toString()));
        return result;
    }

    private boolean isOwnedByEntry(Path file, List<Entry> entries) {
        for (Entry entry : entries) {
            if (entry.path != null && sameFile(file, entry.path)) {
                return true;
            }
        }
        return false;
    }

    private boolean repair(IntegrityReport report, Properties properties) {
        boolean indexChanged = false;
        for (Entry entry : report.entries) {
            if (entry.shared) {
                continue;
            }
            if (entry.broken) {
                deleteBrokenPath(entry.path);
                properties.remove(entry.description);
                indexChanged = true;
            } else if (entry.resolved) {
                deleteRuleFileForInitialization(entry.path);
                properties.remove(entry.description);
                indexChanged = true;
            }
        }
        for (Entry entry : report.entries) {
            if (!entry.shared && !entry.broken && !entry.resolved && entry.misplaced && !entry.colliding && !entry.occupied) {
                moveEntry(entry);
                properties.setProperty(entry.description, entry.derived);
                indexChanged = true;
            }
        }
        return indexChanged;
    }

    private void moveEntry(Entry entry) {
        Path source = entry.path;
        Path target = pathForNameOrNull(entry.derived);
        if (source == null || target == null) {
            throw new StoreInitializationFailedException("Cannot move an invalid rule violation file name");
        }
        if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot repair rule '%s': target file '%s' is occupied", entry.description, entry.derived));
        }
        try {
            Path actualSource = source.toRealPath();
            Files.move(actualSource, target, StandardCopyOption.ATOMIC_MOVE);
            if (Files.isSymbolicLink(source)) {
                Files.delete(source);
            }
        } catch (AtomicMoveNotSupportedException e) {
            try {
                Path actualSource = source.toRealPath();
                Files.move(actualSource, target);
                if (Files.isSymbolicLink(source)) {
                    Files.delete(source);
                }
            } catch (IOException moveFailure) {
                throw new StoreInitializationFailedException(moveFailure);
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private void deleteBrokenPath(Path path) {
        if (path == null || !Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
            return;
        }
        if (Files.isSymbolicLink(path) || (isIndex(path)
                && !path.toAbsolutePath().normalize().equals(storedRulesFile.toAbsolutePath().normalize()))) {
            try {
                Files.delete(path);
            } catch (IOException e) {
                throw new StoreInitializationFailedException(e);
            }
        }
    }

    private void deleteRuleFileForInitialization(Path path) {
        try {
            if (path == null || !Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
                return;
            }
            Path actualPath = path.toRealPath();
            Files.delete(actualPath);
            if (Files.isSymbolicLink(path)) {
                Files.delete(path);
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private void deleteRuleFileForUpdate(Path path) {
        try {
            if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
                return;
            }
            Path actualPath = path.toRealPath();
            Files.delete(actualPath);
            if (Files.isSymbolicLink(path)) {
                Files.delete(path);
            }
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private Path pathForName(String name) {
        try {
            Path path = Paths.get(name);
            if (path.isAbsolute() || path.getNameCount() != 1) {
                throw new InvalidPathException(name, "not a direct relative file name");
            }
            return storeFolder.toPath().resolve(path);
        } catch (InvalidPathException e) {
            throw e;
        }
    }

    private Path pathForNameOrNull(String name) {
        if (name == null) {
            return null;
        }
        try {
            return pathForName(name);
        } catch (RuntimeException e) {
            return null;
        }
    }

    private boolean isDirectChild(Path path) {
        if (path == null || path.isAbsolute() && !path.toAbsolutePath().normalize().startsWith(storeFolder.toPath().toAbsolutePath().normalize())) {
            return false;
        }
        Path folder = storeFolder.toPath().toAbsolutePath().normalize();
        Path normalized = path.toAbsolutePath().normalize();
        return folder.equals(normalized.getParent());
    }

    private Path realFolder() {
        try {
            return storeFolder.toPath().toRealPath();
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private boolean isIndex(Path path) {
        if (path == null) {
            return false;
        }
        if (path.toAbsolutePath().normalize().equals(storedRulesFile.toAbsolutePath().normalize())) {
            return true;
        }
        return sameFile(path, storedRulesFile);
    }

    private boolean sameFile(Path left, Path right) {
        try {
            return Files.exists(left, LinkOption.NOFOLLOW_LINKS)
                    && Files.exists(right, LinkOption.NOFOLLOW_LINKS)
                    && Files.isSameFile(left, right);
        } catch (IOException | SecurityException e) {
            return false;
        }
    }

    private String findRuleKey(Properties properties, String description) {
        if (properties.containsKey(description)) {
            return description;
        }
        String normalizedDescription = ensureUnixLineBreaks(description);
        for (String key : properties.stringPropertyNames()) {
            if (ensureUnixLineBreaks(key).equals(normalizedDescription)) {
                return key;
            }
        }
        return null;
    }

    private String ensureUnixLineBreaks(String string) {
        return string.replace("\r\n", "\n");
    }

    private void addTo(Map<String, List<Entry>> map, String key, Entry entry) {
        List<Entry> values = map.get(key);
        if (values == null) {
            values = new ArrayList<>();
            map.put(key, values);
        }
        values.add(entry);
    }

    private static void deleteQuietly(Path path) {
        if (path != null) {
            try {
                Files.deleteIfExists(path);
            } catch (IOException ignored) {
                // A failed cleanup must not hide the operation's original failure.
            }
        }
    }

    private final class FileSyncedProperties {
        private final Properties properties;

        private FileSyncedProperties(Properties properties) {
            this.properties = properties;
        }
    }

    private final class Entry {
        private final String description;
        private final String fileName;
        private final String derived;
        private final Path path;
        private Path target;
        private boolean direct;
        private boolean regular;
        private boolean index;
        private boolean broken;
        private boolean resolved;
        private boolean misplaced;
        private boolean shared;
        private boolean colliding;
        private boolean occupied;

        private Entry(String description, String fileName, String derived, Path path) {
            this.description = description;
            this.fileName = fileName;
            this.derived = derived;
            this.path = path;
        }
    }

    private final class IntegrityReport {
        private final List<Entry> entries;
        private final List<Path> unownedFiles;

        private IntegrityReport(List<Entry> entries, List<Path> unownedFiles) {
            this.entries = entries;
            this.unownedFiles = unownedFiles;
        }

        private boolean hasProblems() {
            for (Entry entry : entries) {
                if (entry.broken || entry.resolved || entry.shared || entry.misplaced || entry.colliding || entry.occupied) {
                    return true;
                }
            }
            return !unownedFiles.isEmpty();
        }

        private String message(boolean updateAllowed) {
            StringBuilder result = new StringBuilder();
            result.append("Violation store integrity check failed (default.allowStoreUpdate=")
                    .append(updateAllowed).append("):");
            appendEntries(result, "broken", entriesFor(entry -> entry.broken));
            appendEntries(result, "resolved", entriesFor(entry -> entry.resolved));
            appendEntries(result, "shared", entriesFor(entry -> entry.shared));
            appendEntries(result, "misplaced", entriesFor(entry -> entry.misplaced));
            appendEntries(result, "colliding", entriesFor(entry -> entry.colliding));
            appendEntries(result, "occupied", entriesFor(entry -> entry.occupied));
            if (!unownedFiles.isEmpty()) {
                result.append("\nunowned files:");
                for (Path file : unownedFiles) {
                    result.append("\n  ").append(file.getFileName());
                }
            }
            return result.toString();
        }

        private List<Entry> entriesFor(java.util.function.Predicate<Entry> predicate) {
            List<Entry> result = new ArrayList<>();
            for (Entry entry : entries) {
                if (predicate.test(entry)) {
                    result.add(entry);
                }
            }
            result.sort(Comparator.comparing((Entry entry) -> entry.description).thenComparing(entry -> entry.fileName));
            return result;
        }

        private void appendEntries(StringBuilder result, String condition, List<Entry> matchingEntries) {
            if (!matchingEntries.isEmpty()) {
                result.append("\n").append(condition).append(" entries:");
                for (Entry entry : matchingEntries) {
                    result.append("\n  ").append(entry.description).append(" -> ").append(entry.fileName);
                }
            }
        }
    }

    private static final class DescriptionRuleViolationFileNameStrategy implements RuleViolationFileNameStrategy {
        @Override
        public String createRuleFileName(String ruleDescription) {
            String selectedWord = null;
            Matcher matcher = DESCRIPTION_WORD.matcher(ruleDescription);
            while (matcher.find()) {
                selectedWord = matcher.group(1);
            }
            String prefix = selectedWord == null ? "rule" : selectedWord;
            return prefix + "-" + sha256(ruleDescription);
        }

        private static String sha256(String value) {
            try {
                byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
                StringBuilder result = new StringBuilder(digest.length * 2);
                for (byte item : digest) {
                    result.append(Character.forDigit((item >>> 4) & 0xf, 16));
                    result.append(Character.forDigit(item & 0xf, 16));
                }
                return result.toString();
            } catch (NoSuchAlgorithmException e) {
                throw new IllegalStateException(e);
            }
        }
    }

    /**
     * Allows to adjust the rule violation file names of {@link TextFileBasedViolationStore}.
     *
     * @see TextFileBasedViolationStore#TextFileBasedViolationStore(RuleViolationFileNameStrategy)
     */
    @FunctionalInterface
    @PublicAPI(usage = INHERITANCE)
    public interface RuleViolationFileNameStrategy {
        /**
         * Returns the file name to store violations of an {@link ArchRule}, possibly based on the rule description.
